import{z as A,x as c,o as l,c as n,q as d,j as r,D as e,d as B,s,S as t,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"slab","description":"","frontmatter":{"title":"slab","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/slab-allocator.md","filePath":"cs/slab-allocator.md","lastUpdated":1791413859000}'),i={name:"cs/slab-allocator.md"};function b(p,a,m,h,u,D){const o=c("Mermaid");return l(),n("div",null,[a[2]||(a[2]=d('<h1 id="slab" tabindex="-1">slab <a class="header-anchor" href="#slab" aria-label="Permalink to &quot;slab&quot;">​</a></h1><div class="epigraph"><p>同类内核对象从专用缓存里取：一页切成等长槽，构造函数只在首次填充时跑，避免每次从 buddy 要页再初始化。</p><footer>—— 据 Bonwick, The Slab Allocator, USENIX 1994；Love 对 SLAB/SLUB 的整理</footer></div><p><a href="/cs/buddy-allocator">上一课</a>给出页级块。inode、dentry、页表项描述符大小远小于一页，若每个对象 <code>alloc_pages(0)</code>，内碎片与初始化成本爆炸。<a href="/cs/vfs">VFS</a> 尚未讲，但对象缓存必须先存在。缺口是 <strong>slab</strong>：按类型的对象工厂，建立在 buddy 页之上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核分配有两个坏极端：全走 buddy（浪费），或一个全局字节堆（碎片与锁）。Bonwick 的方法：每种对象一个 cache，cache 持有若干 slab（一页或几页），slab 内空闲对象链表。分配 O(1) 取槽；释放回本 cache。着色（colouring）错开对象在页内偏移，减轻 Cache 行冲突。缺口不是用户 malloc 算法，而是内核里生命周期相似的对象。</p><p>本课不把 SLAB、SLOB、SLUB 三种实现做成对照表考试。</p><p><span class="marginnote">SLUB 简化了每 CPU 的部分数组，减少锁。对象可以有构造/析构。过大的对象仍直接走 buddy。</span></p><p><span class="marginnote">数字实例：一个 <code>task_struct</code> 约几 KB、一个 dentry 约百来字节。若为每个 dentry 单独向 buddy 要一页（\\(4\\,\\mathrm{KB}\\)），百字节的请求吃掉整页——内碎片超过 \\(95\\%\\)。切成等长槽后，一页能装几十个 dentry，碎片最多只浪费「整页除不尽」的那一小截。</span></p><p><span class="marginnote">常见误区：初学者容易把 slab 与用户态 malloc 当成同类替代品。分工其实分层：buddy 管<strong>页</strong>，slab 在页上按<strong>对象类型</strong>切槽，用户 malloc 又在另一套 arena 上做——内核 <code>kmalloc</code> 底下就是 slab，用户 <code>malloc</code> 根本摸不到 buddy。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>kmem_cache_create</code> 登记大小与对齐。<code>kmem_cache_alloc</code> 从本 CPU 空闲槽取；没有则向 buddy 要一页填满对象。释放不立即还页，直到整页空闲或回收器收缩。与用户态对照：libc 的 arena 是进程私有；slab 是全核共享（加锁或 per-CPU）。缺页路径上分配的 <code>anon_vma</code> 一类对象走这里。</p>',11)),(l(),r(t,null,{default:e(()=>[s(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TYPE%5B%22%E5%AF%B9%E8%B1%A1%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20CACHE%5B%22kmem_cache%22%5D%0A%20%20CACHE%20--%3E%20SLAB%5B%22%E9%A1%B5%E5%88%87%E6%88%90%E6%A7%BD%22%5D%0A%20%20SLAB%20--%3E%20OBJ%5B%22%E5%88%86%E9%85%8D%2F%E9%87%8A%E6%94%BE%20O(1)%22%5D%0A%20%20CACHE%20--%3E%20BUD%5B%22%E7%BC%BA%E9%A1%B5%E6%97%B6%E9%97%AE%20buddy%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"slab 把「页」变成「类型化内存」，让 VFS 与网络协议栈的热点分配不再打 buddy 锁。回收时 shrinker 可以丢掉空 slab，把页还给 buddy，再给用户缺页用。不要把 slab 当成安全隔离：同页上的对象仍共享帧，越界写会破坏邻居——这是内核编程纪律，不是本课的利用指南。",-1)),a[5]||(a[5]=E("p",null,"一个对象从生到死走哪条路？关键在于「释放不等于归还」：",-1)),(l(),r(t,null,{default:e(()=>[s(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22cache%20%E5%BB%BA%E5%A5%BD%EF%BC%9A%E5%B8%B8%E9%A9%BB%E5%8D%8A%E6%BB%A1%2F%E6%BB%A1%2F%E7%A9%BA%E4%B8%89%E5%88%97%20slab%22%5D%20--%3E%20B%5B%22alloc%EF%BC%9A%E4%BB%8E%E6%9C%AC%20CPU%20%E5%8D%8A%E6%BB%A1%E5%88%97%E5%8F%96%E7%A9%BA%E9%97%B2%E6%A7%BD%22%5D%0A%20%20B%20--%3E%20C%7B%22%E5%8D%8A%E6%BB%A1%E5%88%97%E6%9C%89%E6%A7%BD%3F%22%7D%0A%20%20C%20--%20%E6%9C%89%20--%3E%20D%5B%22O(1)%20%E7%9B%B4%E6%8E%A5%E7%BB%99%3Cbr%3E%E4%B8%8D%E8%B7%91%E6%9E%84%E9%80%A0%EF%BC%88%E5%B7%B2%E5%88%9D%E5%A7%8B%E5%8C%96%E8%BF%87%EF%BC%89%22%5D%0A%20%20C%20--%20%E6%97%A0%20--%3E%20E%5B%22%E9%97%AE%20buddy%20%E8%A6%81%E6%96%B0%E9%A1%B5%3Cbr%3E%E6%96%B0%E5%AF%B9%E8%B1%A1%E6%89%8D%E8%B7%91%E4%B8%80%E6%AC%A1%E6%9E%84%E9%80%A0%22%5D%0A%20%20D%20--%3E%20F%5B%22free%EF%BC%9A%E5%AF%B9%E8%B1%A1%E6%94%BE%E5%9B%9E%E7%A9%BA%E9%97%B2%E6%A7%BD%3Cbr%3E%E9%A1%B5%E4%BB%8D%E7%95%99%E5%9C%A8%20cache%20%E9%87%8C%22%5D%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%20G%7B%22%E6%95%B4%E9%A1%B5%E9%83%BD%E7%A9%BA%3F%22%7D%0A%20%20G%20--%20%E5%90%A6%20--%3E%20H%5B%22%E9%A1%B5%E7%BB%A7%E7%BB%AD%E7%BC%93%E5%AD%98%EF%BC%9A%E7%AD%89%E4%B8%8B%E6%AC%A1%E5%88%86%E9%85%8D%E5%A4%8D%E7%94%A8%22%5D%0A%20%20G%20--%20%E6%98%AF%20--%3E%20I%5B%22shrinker%20%E5%8F%AF%E6%8A%8A%E7%A9%BA%20slab%20%E8%BF%98%20buddy%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=d('<p>直觉类比：像餐厅备好的桌位——客人走了（free）桌子不拆（页不还），擦干净就留给下一桌；只有整间包厢彻底空置、且生意冷清（内存压力）时才拆掉桌位退回场地。</p><p>这一步如果做错了——比如 free 时立刻还页——下一个同类型对象就要重走「要页 + 重新初始化」的全套流程，<code>fork</code> 风暴这类高频分配会把 buddy 锁打爆。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>kmalloc</code> 按尺寸的通用 cache 的全部档位表。不保证实时路径无锁。下一课：当 buddy 也空了，谁去收缩 slab、页 Cache 与匿名页。</p><p>后课默认：小对象有 cache。内存压力下如何把页从 cache 与文件页里挤出来，下一课回收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>slab 在 buddy 页上为同类对象提供槽位缓存。</li><li>减少碎片与重复初始化；空 slab 可还给 buddy。</li><li>压力下的收缩是 shrinker 的缺口。</li><li>出处：Bonwick, USENIX 1994；Love, <em>LKD</em>；Bovet and Cesati, <em>ULK</em>。</li></ul>',7))])}const f=A(i,[["render",b]]);export{_ as __pageData,f as default};
